                bars[symbol] = None
            else:
                bars[symbol] = data.Bars[symbol]

        spy_buy_cross = False
        spy_sell_cross = False
        aapl_buy_signal = False
        aapl_sell_signal = False
        aapl_close = None

        spy_bar = bars[self.spy]
        if spy_bar is not None:
            previous_close = self.previous_spy_close
            previous_sma = self.previous_spy_sma

            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

            current_close = spy_bar.Close
            current_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None

            if (
                previous_close is not None
                and previous_sma is not None
                and current_sma is not None
            ):
                spy_buy_cross = (
                    previous_close <= previous_sma
                    and current_close > current_sma
                )
                spy_sell_cross = (
                    previous_close >= previous_sma
                    and current_close < current_sma
                )

            self.previous_spy_close = current_close
            self.previous_spy_sma = current_sma

